<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../config/db.php';
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: index.php');exit;}verify_csrf();
try{$sale=(int)($_POST['sale_id']??0);$driver=(int)($_POST['driver_id']??0);$addr=trim((string)($_POST['delivery_address']??''));$date=(string)($_POST['delivery_date']??date('Y-m-d'));$notes=trim((string)($_POST['notes']??''));if($sale<=0||$addr==='')throw new RuntimeException('Select a sale and enter a delivery address.');$conn->beginTransaction();$s=$conn->prepare("SELECT s.*,c.id customer_id FROM sales s LEFT JOIN customers c ON c.id=s.customer_id LEFT JOIN deliveries d ON d.sale_id=s.id WHERE s.id=? AND s.sale_status='Completed' AND d.id IS NULL FOR UPDATE");$s->execute([$sale]);$row=$s->fetch();if(!$row)throw new RuntimeException('Sale is invalid or already has a delivery.');$prefix=(string)($conn->query("SELECT setting_value FROM settings WHERE setting_key='delivery_prefix' LIMIT 1")->fetchColumn()?:'SS-DEL');$num=$prefix.'-'.date('YmdHis').'-'.strtoupper(bin2hex(random_bytes(2)));$s=$conn->prepare("INSERT INTO deliveries (delivery_number,sale_id,customer_id,driver_id,delivery_address,delivery_date,status,notes) VALUES (?,?,?,?,?,?,?,?)");$s->execute([$num,$sale,$row['customer_id']?:null,$driver?:null,$addr,$date,'Pending',$notes?:null]);$did=(int)$conn->lastInsertId();$items=$conn->prepare("SELECT product_id,quantity FROM sale_items WHERE sale_id=?");$items->execute([$sale]);$ins=$conn->prepare("INSERT INTO delivery_items (delivery_id,product_id,quantity) VALUES (?,?,?)");foreach($items->fetchAll() as $i)$ins->execute([$did,$i['product_id'],$i['quantity']]);$conn->commit();$_SESSION['delivery_flash']='Delivery '.$num.' created.';}catch(Throwable $e){if($conn->inTransaction())$conn->rollBack();$_SESSION['delivery_flash']='Delivery failed: '.$e->getMessage();}header('Location: index.php');exit;